mapper.select:
SELECT LP.DesignId, LP.LayoutCode, LP.ChnlCode, LP.ProdCode, LP.LocType, LP.ProdSeq,
       LP.Remark, LP.State,
       LP.RegistDate, LP.RegistId, LP.RegistName, LP.ChangeDate, LP.ChangeId, LP.ChangeName,
       PH.ProdName, PH.SalePrice, PH.SaleYn, PH.SupplyQty, PH.ImgUrl80,
       PC.CpnAmt AS ProdCpnAmt, PT.PointAmt
FROM shopion.tStrLayoutProdApply LP
INNER JOIN shopion.tPrdProd PH ON LP.ProdCode = PH.ProdCode
LEFT JOIN shopion.tStrProdCpnProd CPP ON LP.ChnlCode = CPP.ChnlCode AND LP.ProdCode = CPP.ProdCode
LEFT JOIN shopion.tStrProdCpn PC ON CPP.CpnId = PC.CpnId
LEFT JOIN shopion.tStrPointProd PP ON LP.ChnlCode = PP.ChnlCode AND LP.ProdCode = PP.ProdCode
LEFT JOIN shopion.tStrPoint PT ON PP.PointId = PT.PointId


        AND LP.DesignId = #{pDesignId}


        AND LP.LayoutCode IN

            #{item}



        AND LP.LayoutCode = #{pLayoutCode}


        AND LP.ChnlCode = #{pChnlCode}




                AND PH.SaleYn > 0


                AND PH.SaleYn = #{pSaleYn}




        AND PH.SupplyQty > 0


ORDER BY LP.ProdSeq

    LIMIT #{topCnt}


    LIMIT #{startNum}, #{countPerPage}

SELECT COUNT(*)
FROM shopion.tStrLayoutProdApply LP
INNER JOIN shopion.tPrdProd PH ON LP.ProdCode = PH.ProdCode


        AND LP.DesignId = #{pDesignId}


        AND LP.LayoutCode = #{pLayoutCode}


        AND LP.ChnlCode = #{pChnlCode}




                AND PH.SaleYn > 0


                AND PH.SaleYn = #{pSaleYn}
